import React, { useEffect, useState } from "react";

const EmployeeList = () => {
  const [employees, setEmployees] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchEmployees = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(
        "https://backend.jotish.in/backend_dev/gettabledata.php",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ username: "test", password: "123456" }),
        }
      );

      if (!response.ok) {
        throw new Error("Network response was not ok");
      }

      const data = await response.json();

      // Ensure we have TABLE_DATA.data
      if (data.TABLE_DATA && data.TABLE_DATA.data) {
        setEmployees(data.TABLE_DATA.data);
      } else {
        setEmployees([]);
      }
    } catch (err) {
      console.error(err);
      setError("Failed to fetch employee data.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEmployees();
  }, []);

  if (loading) return <p>Loading employees...</p>;
  if (error) return <p style={{ color: "red" }}>{error}</p>;

  // Handle empty employees array
  if (!Array.isArray(employees) || employees.length === 0) {
    return (
      <div>
        <h2>Employee List</h2>
        <button onClick={fetchEmployees}>Refresh</button>
        <p>No employees found.</p>
      </div>
    );
  }

  // Use first row to get column headers if it's an array
  const headers =
    Array.isArray(employees[0]) && employees[0].length
      ? employees[0].map((_, i) => `Column ${i + 1}`)
      : [];

  return (
    <div>
      <h2>Employee List</h2>
      <button onClick={() => alert("View Salary Chart clicked!")}>
        View Salary Chart
      </button>
      <button onClick={fetchEmployees} style={{ marginLeft: "10px" }}>
        Refresh
      </button>

      <table border="1" cellPadding="10" cellSpacing="0" style={{ marginTop: "10px" }}>
        <thead>
          <tr>
            {headers.map((header, i) => (
              <th key={i}>{header}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {employees.map((emp, index) => (
            <tr key={index}>
              {Array.isArray(emp)
                ? emp.map((value, i) => <td key={i}>{value}</td>)
                : <td>{emp}</td>}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default EmployeeList;
